-- P5 Humanities first term: 480 original multiple-choice questions (80 per unit).
-- Based on the curriculum scope of the supplied teaching resources; wording is original.
-- Safe to run repeatedly: existing nodes and matching question texts are retained.
begin;

do $$ begin
  if not exists(select 1 from public.curriculum_subjects where grade='P5' and code='humanities') then
    raise exception 'P5 Humanities subject was not found (expected code: humanities).';
  end if;
end $$;

insert into public.curriculum_domains(subject_id,code,name_zh,name_en,sort_order)
select s.id,'first_term','人文科上學期','P5 Humanities First Term',1
from public.curriculum_subjects s
where s.grade='P5' and s.code='humanities'
  and not exists(select 1 from public.curriculum_domains d where d.subject_id=s.id and d.code='first_term');

insert into public.curriculum_nodes(domain_id,code,title_zh,title_en,difficulty,sort_order,is_active)
select d.id,v.code,v.title_zh,v.title_en,v.difficulty,v.sort_order,true
from public.curriculum_domains d
join public.curriculum_subjects s on s.id=d.subject_id
cross join(values
('5H1','預防意外與簡單急救','Accident Prevention and Basic First Aid',2,1),
('5H2','家居、戶外及公共安全','Safety at Home, Outdoors and in Public Places',3,2),
('5H3','青春期的生理與心理變化','Physical and Psychological Changes during Puberty',3,3),
('5H4','情緒管理、壓力與拒絕欺凌','Emotion Management, Stress and Bullying Prevention',3,4),
('5H5','瞭解自己與面對挑戰','Understanding Yourself and Facing Challenges',3,5),
('5H6','理財、電子消費與綠色消費','Money Management, E-consumption and Green Consumption',4,6)
)v(code,title_zh,title_en,difficulty,sort_order)
where s.grade='P5' and s.code='humanities' and d.code='first_term'
  and not exists(select 1 from public.curriculum_nodes n where n.code=v.code);

create temporary table tmp_p5_humanities(
  node_code text not null,
  category text not null,
  question_text text not null,
  options jsonb not null,
  correct_answer jsonb not null,
  explanation text not null,
  hint text not null,
  difficulty integer not null
) on commit drop;

