  ('5H1','表格資料題','【表格資料題】
【資料是否充分】一名同學採用「遇嚴重事故立即通知成人並致電999」一天後，沒有出現受傷個案。他便說：「這個方法對所有人永遠有效。」
下列哪項評價最合理？','[{"id":"a","text":"資料不足，應增加人數和觀察時間"},{"id":"b","text":"結論必定正確，因為結果是零"},{"id":"c","text":"只需再問同一名同學一次"},{"id":"d","text":"不用記錄其他可能影響結果的因素"}]'::jsonb,'"a"'::jsonb,'只有一人、一天的資料，樣本和時間都不足，不能推論對所有人永遠有效；應擴大樣本並持續觀察。','判斷樣本是否足夠，以及結論有沒有超出資料能支持的範圍。',4),
