根據圖意，哪項描述最合理？','[{"id":"a","text":"右圖人物較合宜，因為快捷最重要"},{"id":"b","text":"兩人的做法必定同樣安全"},{"id":"c","text":"只看人物表情便可判斷對錯"},{"id":"d","text":"左圖人物的做法較合宜，因為充足準備和結伴可降低戶外風險"}]'::jsonb,'"d"'::jsonb,'左圖展示「帶備水和通訊工具，依指定路線同行」，符合課文原則；右圖的做法會增加風險。','比較兩幅圖中人物的實際行動，不要只看表情。',2),
  ('5H2','表格資料題','【表格資料題】
【資料是否充分】一名同學採用「發現破損設施應遠離並通知管理員」一天後，沒有出現危險事件。他便說：「這個方法對所有人永遠有效。」
下列哪項評價最合理？','[{"id":"a","text":"不用記錄其他可能影響結果的因素"},{"id":"b","text":"只需再問同一名同學一次"},{"id":"c","text":"資料不足，應增加人數和觀察時間"},{"id":"d","text":"結論必定正確，因為結果是零"}]'::jsonb,'"c"'::jsonb,'只有一人、一天的資料，樣本和時間都不足，不能推論對所有人永遠有效；應擴大樣本並持續觀察。','判斷樣本是否足夠，以及結論有沒有超出資料能支持的範圍。',4),
  ('5H2','表格資料題','【表格資料題】
【雙重條件】選擇與「大型活動安全」有關的方案。條件：所需時間不多於40分鐘，危險事件不多於3宗。
