哪個方案同時符合兩項條件？','[{"id":"a","text":"乙方案"},{"id":"b","text":"甲方案"},{"id":"c","text":"丙方案"},{"id":"d","text":"丁方案"}]'::jsonb,'"c"'::jsonb,'丙方案需時38分鐘（不多於40分鐘），記錄為2宗（不多於3宗），兩項都符合。乙雖記錄較少，但時間超出上限。','逐一檢查每個方案是否「兩項條件」都達標。',1),
  ('5H2','表格資料題','【表格資料題】
