  ('5H3','選出正確答案','【選出正確答案】
關於「個人衞生」，下列哪一項做法正確？','[{"id":"a","text":"共用未清潔毛巾"},{"id":"b","text":"擠破所有暗瘡"},{"id":"c","text":"用香水代替洗澡"},{"id":"d","text":"勤洗澡、換衣並保持皮膚清潔"}]'::jsonb,'"d"'::jsonb,'「勤洗澡、換衣並保持皮膚清潔」正確，因為青春期汗液增加，清潔可減少氣味及皮膚問題。其餘做法可能增加風險。','先找出會保障安全、健康、尊重或資源的做法。',2),
  ('5H3','選出正確答案','【選出正確答案】
