結合數據和課文原則，哪項推論最合理？','[{"id":"a","text":"乙班事件增加，所以乙班方法最好"},{"id":"b","text":"甲班結果較佳，資料支持「明白健康、友誼和親情不能單靠金錢購買」較合宜"},{"id":"c","text":"兩班人數相同，所以不必比較前後變化"},{"id":"d","text":"只要一次結果便能保證以後完全相同"}]'::jsonb,'"b"'::jsonb,'甲班由12元降至4元，乙班則由11元升至16元；在相同人數和觀察期下，資料較支持「明白健康、友誼和親情不能單靠金錢購買」，但仍不能保證未來每次結果相同。','同時比較兩班的前後變化，並留意結論不可超出證據。',1),
  ('5H6','表格資料題','【表格資料題】
【原始數據比較】四組各有30人
甲：採用「先處理基本需要，再考慮想要的物品」｜非必要支出2元
乙：採用「看到減價便全買」｜非必要支出9元
丙：採用「把娛樂視為必需」｜非必要支出7元
丁：採用「用盡零用錢」｜非必要支出8元
哪項結論最符合表中資料？','[{"id":"a","text":"四組結果完全相同"},{"id":"b","text":"資料證明任何方法都能完全消除問題"},{"id":"c","text":"乙組的方法效果最好"},{"id":"d","text":"採用「先處理基本需要，再考慮想要的物品」的一組，非必要支出最少"}]'::jsonb,'"d"'::jsonb,'甲組只有2元非必要支出，少於其餘三組，因此資料支持正確做法較有效；但不能推論它可完全消除問題。','四組人數相同，可直接比較事件數，但不要作「完全保證」的推論。',4);

do $$ declare bad_count integer; begin
  select count(*) into bad_count
  from(values('5H1',80),('5H2',80),('5H3',80),('5H4',80),('5H5',80),('5H6',80)) expected(code,qty)
  where(select count(*) from tmp_p5_humanities t where t.node_code=expected.code)<>expected.qty;
  if bad_count>0 then raise exception 'Per-unit question count validation failed.'; end if;
  if(select count(*) from tmp_p5_humanities)<>480 then raise exception 'Total question count is not 480.'; end if;
  if(select count(*) from tmp_p5_humanities)<>(select count(*) from(select distinct node_code,question_text from tmp_p5_humanities)d) then
    raise exception 'Duplicate question text found.';
  end if;
  if exists(select 1 from tmp_p5_humanities where jsonb_array_length(options)<>4 or correct_answer not in ('"a"'::jsonb,'"b"'::jsonb,'"c"'::jsonb,'"d"'::jsonb)) then
    raise exception 'Invalid options or answer key found.';
  end if;
end $$;

insert into public.questions(node_id,question_type,question_text,options,difficulty,source_type,status)
select n.id,'multiple_choice',t.question_text,t.options,t.difficulty,'teacher','published'
from tmp_p5_humanities t
join public.curriculum_nodes n on n.code=t.node_code
where not exists(select 1 from public.questions q where q.node_id=n.id and q.question_text=t.question_text);

insert into public.question_answer_keys(question_id,correct_answer,explanation,hint)
select q.id,t.correct_answer,t.explanation,t.hint
from tmp_p5_humanities t
join public.curriculum_nodes n on n.code=t.node_code
join public.questions q on q.node_id=n.id and q.question_text=t.question_text
on conflict(question_id) do update set
  correct_answer=excluded.correct_answer,
  explanation=excluded.explanation,
  hint=excluded.hint;

commit;

select n.code,n.title_zh,count(q.id) filter(where q.status='published') as published_questions
from public.curriculum_nodes n
left join public.questions q on q.node_id=n.id
where n.code between '5H1' and '5H6'
group by n.code,n.title_zh
order by n.code;
